// Dự án DEMO — chương trình mẫu (an toàn, không phát lệnh xuống thiết bị)
// 1) Bấm "Kiểm tra" để phân tích tĩnh
// 2) Bấm "Build" để biên dịch phiên bản này
// 3) Bấm "Mô phỏng (twin)" để chạy thử trên bản sao số
START
  WAIT 100        // chờ 100ms
  SET output = 1  // bật đầu ra minh hoạ
  WAIT 100
  SET output = 0
END
